 async function submitEditor(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!editor)return;const fd=new FormData(e.currentTarget),p:Record<string,unknown>={...editor.values};for(const f of editor.fields)p[f.key]=String(fd.get(f.key)||'');for(const k of ['capacity','price','weeks','amount'])if(k in p)p[k]=Number(p[k]);if('joinedAt'in p&&!p.joinedAt)delete p.joinedAt;if('number'in p)p.number=p.number===''?null:Number(p.number);for(const k of ['startsAt','endsAt'])if(typeof p[k]==='string'&&p[k]&&editor.action!=='season')p[k]=new Date(p[k] as string).toISOString();if(editor.action==='form'){p.fields=String(p.extra||'').split('\n').filter(x=>x.trim()).map((line,i)=>({key:'campo_'+(i+1),label:line.replace(/\*$/,'').trim(),required:line.trim().endsWith('*')}));delete p.extra;}if(editor.action==='member')p.teamIds=String(p.teamIds||'').split(',').map(x=>x.trim()).filter(Boolean);if(await command(editor.action,p)){close();notice('Cambios guardados.');}}
 async function exportBank(){setBusy(true);try{const r=await api('/api/bank/export',{method:'POST',body:JSON.stringify({seasonId})});const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='cdir-cuentas.csv';a.click();URL.revokeObjectURL(url);notice('Exportación auditada.');await load();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function upload(file:File,playerId:string){setBusy(true);try{const data=new FormData();data.set('file',file);data.set('playerId',playerId);const r=await fetch('/api/files',{method:'POST',headers:await authHeaders(),body:data});if(!r.ok)throw new Error((await r.json()).message);await load();notice('Documento privado guardado.');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function download(id:string){try{const r=await api('/api/files/'+id);const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=s.files.find(f=>f.id===id)?.name||'documento';a.click();URL.revokeObjectURL(url);}catch(e){setError((e as Error).message);}}
